override fun onMeasure(widthMeasureSpec: Int, heightMeasureSpec: Int) {
    // 这里如何正确处理 wrap_content？
}

questions.explanation:
Android 的测量规格（MeasureSpec）由 mode + size 组成：EXACTLY 对应 match_parent 和具体 dp 值，AT_MOST 对应 wrap_content，UNSPECIFIED 用于 ScrollView 等不限制子 View 的场景。View.getDefaultSize() 的实现是：如果是 AT_MOST 或 EXACTLY，都直接返回 MeasureSpec.getSize()，这就是 wrap_content 失效的根源。自定义 View 需要手动处理 AT_MOST 模式，建议代码：
val specMode = MeasureSpec.getMode(measureSpec)
val specSize = MeasureSpec.getSize(measureSpec)
val result = if (specMode == MeasureSpec.AT_MOST) {
    min(defaultSize, specSize)
} else {
    specSize
}

